INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('02014162-648d-5109-acb6-59287b992b45'::uuid, '95c9cdbe-e880-5ce3-8319-88a44f7439ac'::uuid, 'Maîtrise d''œuvre architecturale clé en main', 'Mission complète portée par le cabinet de Hakim Benjelloun : conception générale, architecture d''intérieur, mobilier et suivi jusqu''à la réalisation. Programmes résidentiels, hôteliers, sièges et équipements. Tarif sur devis selon l''échelle et les phases confiées.', 'Architecture', 'https://chb.kscreasupport.com/wp-content/uploads/2023/07/villa-1.jpg', '["https://chb.kscreasupport.com/wp-content/uploads/2023/07/villa-1.jpg", "https://chb.kscreasupport.com/wp-content/uploads/2023/07/casa-priv3.jpg", "https://chb.kscreasupport.com/wp-content/uploads/2023/07/villa.jpg"]'::jsonb, '["Étude", "Réalisation", "Accompagnement"]'::jsonb, '["Conception générale de l''architecture", "Architecture d''intérieur et agencement", "Mobilier et design d''objet", "Suivi jusqu''à la réalisation"]'::jsonb, '[]'::jsonb, 'devis', '', 'Selon le dossier', 'maroc', '[]'::jsonb, '', TRUE, FALSE, '["Promoteurs", "Entreprises", "Investisseurs"]'::jsonb, '', '["National", "International"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('ba70d75e-747f-593d-a35b-e18a8c9d3abe'::uuid, 'e5f9fff7-415f-5749-8468-151a926d4f4e'::uuid, 'Entreprise générale de bâtiments', 'Mission d''entreprise générale sur bâtiments et ouvrages : gros œuvre, étanchéité et coordination du lot confié. Chiffrage sur dossier de consultation (métrés, planning, périmètre des corps d''état). Aucun prix au m² hors appel d''offres.', 'Structure', 'https://tgcc.ma/wp-content/uploads/2025/12/Grand_theatre.jpg', '["https://tgcc.ma/wp-content/uploads/2025/12/Grand_theatre.jpg", "https://tgcc.ma/wp-content/uploads/2025/12/TGCC-UM6P-RABAT_result.jpg", "https://tgcc.ma/wp-content/uploads/2025/12/Tremie-Dar-Bouazza-1_result.jpg"]'::jsonb, '["Réalisation"]'::jsonb, '["Gros œuvre", "Étanchéité", "Coordination du lot confié"]'::jsonb, '["Bâtiment hospitalier", "Bâtiment tertiaire", "Ouvrage"]'::jsonb, 'devis', '', 'Selon le dossier', 'maroc', '[]'::jsonb, '', TRUE, FALSE, '["Promoteurs", "Entreprises"]'::jsonb, '', '[]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('1d93040e-1660-5102-bec7-5c464fae6c91'::uuid, 'cef92b70-9083-53cd-9f2d-ffb47877669e'::uuid, 'Développement de programmes immobiliers', 'Montage, commercialisation et suivi jusqu''à la livraison de programmes résidentiels et tertiaires. Le prix d''un lot est celui du programme, communiqué sur le dossier de vente. Pas de forfait de prestation séparé.', 'Promoteur immobilier', 'https://cdgdev.ma/sites/default/files/2025-03/Arborelles%20020624_3%20-%20Photo.jpg', '["https://cdgdev.ma/sites/default/files/2025-03/Arborelles%20020624_3%20-%20Photo.jpg", "https://cdgdev.ma/sites/default/files/2025-03/DPR-CGI-TAGHAZOUT-Bis-Oct-2024-920x860.png", "https://cdgdev.ma/sites/default/files/2024-12/Casa%20Green%20Town%20_%20CASABLANCA-0082024_%C2%A9Said%20Mrigua_SAID%20MRIGUA%281%29.jpg"]'::jsonb, '["Réalisation", "Accompagnement", "Gestion"]'::jsonb, '["Montage du programme", "Commercialisation des lots (VEFA)", "Suivi jusqu''à la livraison"]'::jsonb, '["Logement", "Plateau tertiaire", "Villa"]'::jsonb, 'devis', '', 'Selon le dossier', 'maroc', '[]'::jsonb, '', TRUE, FALSE, '["Particuliers", "Investisseurs", "Entreprises"]'::jsonb, '', '[]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '1.2.1' LIMIT 1));
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('a6175808-3405-502e-9622-fa636d1ef1bc'::uuid, 'c9917c8b-b34c-5970-a885-abe9b157a66f'::uuid, 'Rénovation intérieure clé en main', 'Rénovation et aménagement intérieur à Casablanca : appartements dès 60 m², bureaux et locaux au cas par cas. Du gros œuvre aux finitions, un seul interlocuteur coordonne maçons, plombiers, électriciens, menuisiers et peintres. Montant sur devis selon l''état du bien et le niveau de finition.', 'Rénovation intérieure', 'https://interstyledesign.ma/images/projets/renovation-racine-01.webp', '["https://interstyledesign.ma/images/projets/renovation-racine-01.webp", "https://interstyledesign.ma/images/projets/renovation-racine-02.webp", "https://interstyledesign.ma/images/projets/aeria-hs-1.webp", "https://interstyledesign.ma/images/conception-2d-3d-casablanca.webp"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Appartements à partir de 60 m²", "Tous corps d''état jusqu''aux finitions", "Coordination du chantier", "Livraison clé en main"]'::jsonb, '["Bien livré brut", "Plateau de bureaux", "Villa en cours de construction"]'::jsonb, 'devis', '', 'Selon le dossier', 'villes', '["Casablanca"]'::jsonb, '', TRUE, TRUE, '["Particuliers", "Propriétaires", "Entreprises"]'::jsonb, '', '[]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '4.1.2' LIMIT 1));
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('fd7dbc46-1c13-50c7-87c9-eb70a02818dd'::uuid, '0c28bc7a-c563-5a3c-9d06-aee3467996c2'::uuid, 'Études techniques et suivi de travaux', 'Études techniques et suivi de réalisation pour maîtres d''ouvrage : structure, fluides, économie, ordonnancement. Honoraires sur devis. Suivi possible au Maroc, y compris à distance lorsque le dossier le permet.', 'Bureau d''études', 'https://betam.ma/wp-content/uploads/2020/10/etude-general.jpg', '["https://betam.ma/wp-content/uploads/2020/10/etude-general.jpg", "https://betam.ma/wp-content/uploads/2020/10/maitrise-doeuvre.jpg", "https://betam.ma/wp-content/uploads/2020/10/Assistance-Maitrise-douvrage.jpg", "https://betam.ma/wp-content/uploads/2020/09/Un-service-batiment-genie-civil.jpg"]'::jsonb, '["Étude", "Conseil", "Accompagnement"]'::jsonb, '["Études techniques", "Suivi de la réalisation", "Contrôle de l''exécution"]'::jsonb, '["Structure", "Fluides", "Ordonnancement", "Coordination TCE"]'::jsonb, 'devis', '', 'Selon le dossier', 'maroc', '[]'::jsonb, '', TRUE, TRUE, '["Promoteurs", "Entreprises", "Architectes / Bureaux d''études"]'::jsonb, '', '[]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '3.4.2' LIMIT 1));
INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('b4704eaa-c9a0-57ba-b219-0c1846ccb3e0'::uuid, '87fe685f-aabf-509d-aa55-ecadd782ca72'::uuid, 'Sécurisation des ventes et des baux', 'Accompagnement juridique des opérations immobilières : audit des titres et autorisations, promesse et contrat de vente, baux commerciaux, coordination avec le notaire. Pour promoteurs, agences, investisseurs et entreprises à Casablanca et Rabat. Honoraires sur devis.', 'Droit immobilier', 'https://ahlo.ma/wp-content/uploads/2022/04/PHOTO-MENU-ACTIVITES-.jpg', '["https://ahlo.ma/wp-content/uploads/2022/04/PHOTO-MENU-ACTIVITES-.jpg", "https://ahlo.ma/wp-content/uploads/2022/04/PHOTO-MENU-A-PROPOS.jpg", "https://ahlo.ma/wp-content/uploads/2022/05/CABINET-D-AVOCAT-HAJJI-ASSOCIES-CASABLANCA-CABINET-AMIN-HAJJI-MISE-EN-AVANT.jpg"]'::jsonb, '["Conseil", "Accompagnement"]'::jsonb, '["Audit des titres et des autorisations", "Promesse et contrat de vente", "Baux commerciaux et professionnels", "Coordination avec le notaire"]'::jsonb, '["Revue d''un programme", "Contentieux de la construction"]'::jsonb, 'devis', '', 'Selon le dossier', 'villes', '["Casablanca", "Rabat"]'::jsonb, '', TRUE, TRUE, '["Promoteurs", "Investisseurs", "Entreprises"]'::jsonb, '', '["National", "International"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '6.3.1' LIMIT 1));

-- realisations
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('febaf162-8c7b-5cf4-baa0-b30d736ed315'::uuid, '95c9cdbe-e880-5ce3-8319-88a44f7439ac'::uuid, 'Villa privée à Casablanca', 'Résidence privée conçue par CHB Architects : volumes, matières et séquences d''espaces travaillés pour un équilibre contemporain.', '["https://chb.kscreasupport.com/wp-content/uploads/2023/07/villa-1.jpg", "https://chb.kscreasupport.com/wp-content/uploads/2023/07/casa-priv3.jpg", "https://chb.kscreasupport.com/wp-content/uploads/2023/07/villa.jpg"]'::jsonb, 'https://chb.kscreasupport.com/wp-content/uploads/2023/07/villa-1.jpg', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('98a3848b-6557-5c5a-88bc-c84752efc781'::uuid, '95c9cdbe-e880-5ce3-8319-88a44f7439ac'::uuid, 'Siège de bureaux BMCE — Casablanca', 'Siège de bureaux conçu pour BMCE à Casablanca : environ 6 000 m², dix niveaux (deux sous-sols, RDC et sept étages), façade verre, inox, alucobond et ardoise.', '["https://chb.kscreasupport.com/wp-content/uploads/2023/07/villa.jpg", "https://chb.kscreasupport.com/wp-content/uploads/2023/07/casa-priv3.jpg"]'::jsonb, 'https://chb.kscreasupport.com/wp-content/uploads/2023/07/villa.jpg', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '5.1.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('6c4c605c-1aa9-509b-884d-09added575bb'::uuid, 'e5f9fff7-415f-5749-8468-151a926d4f4e'::uuid, 'Grand Théâtre de Casablanca', 'CasArts — 24 000 m² au cœur du quartier historique. Salle de spectacle 1 800 places, théâtre 600 places, salle de musique 450 places. Maître d''ouvrage : Casa Aménagement. Mission TGCC tous corps d''état.', '["https://tgcc.ma/wp-content/uploads/2025/12/Grand_theatre.jpg", "https://tgcc.ma/wp-content/uploads/2025/12/TGCC-BESIX-PEOPLE-071_result.jpg"]'::jsonb, 'https://tgcc.ma/wp-content/uploads/2025/12/Grand_theatre.jpg', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('b62a80fb-92dc-5d38-845e-0e53a718c362'::uuid, 'e5f9fff7-415f-5749-8468-151a926d4f4e'::uuid, 'UM6P de Rabat', 'Campus Université Mohammed VI Polytechnique : +100 000 m² couverts, 856 chambres, parking 10 000 m², écoles et incubateur. Maître d''ouvrage UM6P / OCP.', '["https://tgcc.ma/wp-content/uploads/2025/12/TGCC-UM6P-RABAT_result.jpg"]'::jsonb, 'https://tgcc.ma/wp-content/uploads/2025/12/TGCC-UM6P-RABAT_result.jpg', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('66e497e2-41b4-5a16-8f26-c70d2fea4155'::uuid, 'e5f9fff7-415f-5749-8468-151a926d4f4e'::uuid, 'Trémie Dar Bouazza', 'Ouvrage d''infrastructure urbaine réalisé par TGCC dans le cadre de ses activités travaux publics.', '["https://tgcc.ma/wp-content/uploads/2025/12/Tremie-Dar-Bouazza-1_result.jpg"]'::jsonb, 'https://tgcc.ma/wp-content/uploads/2025/12/Tremie-Dar-Bouazza-1_result.jpg', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('757e4f3a-8046-5e9e-bee6-ff6eda16a910'::uuid, 'e5f9fff7-415f-5749-8468-151a926d4f4e'::uuid, 'Stade Al Barid', 'Équipement sportif d''envergure : réalisation TGCC sur le stade Al Barid.', '["https://tgcc.ma/wp-content/uploads/2026/01/STADE-AL-BARID-73-1_result.jpg"]'::jsonb, 'https://tgcc.ma/wp-content/uploads/2026/01/STADE-AL-BARID-73-1_result.jpg', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '3.1.3' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('cdfe469b-dc58-5c9b-95d0-3e0ceb92a2f1'::uuid, 'cef92b70-9083-53cd-9f2d-ffb47877669e'::uuid, 'Les Arborelles — El Menzeh', 'Programme résidentiel CGI à Rabat : villas et lots haut de gamme, urbanisme responsable et standards de qualité du promoteur.', '["https://cdgdev.ma/sites/default/files/2025-03/Arborelles%20020624_3%20-%20Photo.jpg", "https://cdgdev.ma/sites/default/files/2025-03/VILLA%20D%20%282%29.jpg"]'::jsonb, 'https://cdgdev.ma/sites/default/files/2025-03/Arborelles%20020624_3%20-%20Photo.jpg', 'Rabat', (SELECT id FROM public.internal_categories WHERE code = '1.2.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('4d74def5-b57b-51ef-bf44-846b0c31b368'::uuid, 'cef92b70-9083-53cd-9f2d-ffb47877669e'::uuid, 'Casa Green Town — Casablanca', 'Opération résidentielle CGI à Casablanca, illustrant le positionnement moyen / haut standing du promoteur.', '["https://cdgdev.ma/sites/default/files/2024-12/Casa%20Green%20Town%20_%20CASABLANCA-0082024_%C2%A9Said%20Mrigua_SAID%20MRIGUA%281%29.jpg"]'::jsonb, 'https://cdgdev.ma/sites/default/files/2024-12/Casa%20Green%20Town%20_%20CASABLANCA-0082024_%C2%A9Said%20Mrigua_SAID%20MRIGUA%281%29.jpg', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '1.2.1' LIMIT 1));
